void walk(TreeNode node, int low, int high, List<Integer> kept) {
    if (node == null) return;
    if (node.val >= low && node.val <= high) kept.add(node.val);   // pre-order
    walk(node.left, low, high, kept);
    walk(node.right, low, high, kept);
}

